import json
import os
import subprocess
import sys

CREDS_CACHE = "/opt/opencode/data/.zlib-mcp/.account-env-cache.json"
DOWNLOAD_DIR = "/home/study-agent/data/biblioteca/_incoming"
STATE_FILE = "/opt/opencode/data/.zlib-mcp/.rr-state"
MCP_PKG = "zlib-mcp@0.1.2"

ACCOUNT_NAMES = ["zlib", "zlib2", "zlib3", "zlib4"]
ALIASES = {"zlib": "principal", "zlib2": "conta-b", "zlib3": "conta-c", "zlib4": "conta-d"}


def load_account_envs():
    envs = {}
    if os.path.exists(CREDS_CACHE):
        try:
            envs = json.load(open(CREDS_CACHE))
        except Exception:
            envs = {}
    if not envs:
        # fallback: ler do yaml de credenciais do perfil
        import re
        p = "/home/study-agent/data/perfil/bibliotecario/zlib-credentials.yaml"
        txt = open(p, encoding="utf-8").read()
        blocks = txt.split("- alias:")
        order = ["zlib", "zlib2", "zlib3", "zlib4"]
        for i, b in enumerate(blocks[1:]):
            rid = re.search(r"remix_id:\s*'?([0-9]+)'?", b)
            rkey = re.search(r"remix_key:\s*'?([A-Za-z0-9]+)'?", b)
            if rid and rkey and i < len(order):
                envs[order[i]] = {"ZLIB_REMIX_ID": rid.group(1), "ZLIB_REMIX_KEY": rkey.group(1)}
    return envs


def get_account_env(account):
    envs = load_account_envs()
    if account not in envs:
        raise RuntimeError(f"credenciais nao encontradas para {account} (cache: {list(envs)})")
    base = {"PATH": os.environ.get("PATH", "") + ":/usr/bin:/usr/local/bin",
            "ZLIB_DOWNLOAD_DIR": DOWNLOAD_DIR,
            "HOME": os.environ.get("HOME", "/root")}

